      "hindiMeaning": "शब्दार्थ: अत्र = यहाँ; उपवर्ष-वर्षाविह = उपवर्ष और वर्ष; पाणिनिपिंगलौ = पाणिनि और पिंगल; व्याडिः = व्याडि; वररुचि = वररुचि; पतञ्जली = पतंजलि; इह = यहाँ; परीक्षिताः = परीक्षा देकर/शिक्षित होकर; ख्यातिम् उपजग्मुः = ख्याति (प्रसिद्धि) प्राप्त की।\n\nव्याख्या: कवि राजशेखर अपने 'काव्यमीमांसा' ग्रंथ में कहते हैं कि प्राचीन काल में पाटलिपुत्र शिक्षा का एक महान केंद्र था। यहीं पर उपवर्ष, वर्ष, पाणिनि, पिंगल, व्याडि, वररुचि और पतंजलि जैसे महान विद्वानों ने शिक्षा प्राप्त की, अपनी योग्यता सिद्ध की और पूरे विश्व में प्रसिद्धि पाई।"
