      "marks": 2,
      "answer_hindi_detailed": "विवाह को एक अति पवित्र संस्कार माना जाता है क्योंकि इसी के द्वारा मनुष्य गृहस्थ जीवन में प्रवेश करता है। इसमें कई कर्मकाण्ड होते हैं जैसे- वाग्दान, मंडप निर्माण, कन्यादान, अग्निस्थापना, पाणिग्रहण, लाजाहोम, सप्तपदी और सिन्दूरदान।"
